
export default class AnimateIcon {
    constructor(width, sleep = 0.2, size = 21) {
        // const gifItems = this.gifItems()
        // this.icons = gifItems.filter(item =>  iconKeys.include(item.key))
        this.sleep = sleep
        this.width = width
        this.size = size
        this.timer = null
        this.start = undefined
    }
    begin() {
        const elements = document.querySelectorAll('.marker-animate-gif')
        if (!elements.length) {
            return false
        }
        this.frame = 0
        this.timer = requestAnimationFrame(this.animate.bind(this))
    }
    stop() {
    }
    gifItems() {
        const defaultIconItems = [
            {
              key: 'front_gif',
              url: '../assets/default/icons/front_gif.png',
            },
            {
              key: 'left_gif',
              url: '../assets/default/icons/left_gif.png',
            },
            {
              key: 'bottom_gif',
              url: '../assets/default/icons/bottom_gif.png',
            },
            {
              key: 'right_gif',
              url: '../assets/default/icons/right_gif.png',
            },
            {
              key: 'left2_gif',
              url: '../assets/default/icons/left2_gif.png',
            },
            {
              key: 'right2_gif',
              url: '../assets/default/icons/right2_gif.png',
            },
            {
              key: 'dot_gif',
              url: '../assets/default/icons/dot_gif.png',
            },
            {
              key: 'zoom_gif',
              url: '../assets/default/icons/zoom_gif.png',
            },
            {
              key: 'plus_gif',
              url: '../assets/default/icons/plus_gif.png',
            },
          ]
          for (let index = 1; index <= 34; index++) {
            defaultIconItems.push({
              key: `v2_${index}_gif`,
              url: `../assets/default/icons/${index}_animate.png`,
            })
          }

          return defaultIconItems
    }
    animate(timestamp) {
        if (this.start === undefined) {
            this.start = timestamp
        }

        const elapsed = timestamp - this.start
        if (elapsed > 1000 * this.sleep || this.frame === 0) { 
            const elements = document.querySelectorAll('.marker-animate-gif')
            elements.forEach(element => {
                const width = element.clientWidth
                // const maxPos = width * this.size
                let yPos = 0
                if (this.frame >= this.size) {
                    this.frame = 0
                }
    
                yPos = (this.frame) * width // yPos >= maxPos ? maxPos : 
                element.style.backgroundPosition = `0 -${yPos}px`
                this.frame++
            })
            this.start = undefined
        }


        requestAnimationFrame(this.animate.bind(this))
    }
}
