import { getProduct, getScene, getProductScenes, getHotpots } from '@/api/vr'
import { omit, cloneDeep, debounce, merge, isEqual } from 'lodash'
// eslint-disable-next-line no-unused-vars
import { Viewer, DEFAULTS } from '@photo-sphere-viewer/core'
import { MarkersPlugin } from '@photo-sphere-viewer/markers-plugin'
// eslint-disable-next-line no-unused-vars
import { EquirectangularTilesAdapter } from '@photo-sphere-viewer/equirectangular-tiles-adapter'

// 默认值 start
const defaultVrOptions = omit(DEFAULTS, [
    'panorama',
    'panoData',
    'sphereCorrection',
    'container',
    'plugins',
    'navbar',
    'loadingImg',
])
defaultVrOptions.autorotateSpeed = 0
defaultVrOptions.sphereCorrection = {
    pan: 0,
    tilt: 0,
    roll: 0,
}
export const renderVRMixin = {
    data() {
        return {
            product: null,
            loading: false, // 全景loading
            currentScene: null, // 当前操作的场景
            vrViewer: null, // 渲染的vr
            vrViewerLoaded: false, // vr是否渲染加载完成
            vrOptions: cloneDeep(defaultVrOptions), // vr播放器参数配置
            oldVrOptions: {},
            markersPlugin: null, // 标记插件
            hotpots: [], // 热点
            hotpotMarkerItems: [], // 热点标记
            vrPlugins: [], // vr插件
            vrNavBars: [] // 工具栏
        }
    },
    created() {},
    mounted() {
        // vr播放器设置防抖
        this._applyVrPlayOptions = debounce(() => {
            this.applyVrPlayOptions()
        }, 200)
    },
    methods: {
        // 获取作品详情
        async getProduct(id, callback = null) {
            this.product = await getProduct(id)
            typeof callback === 'function' && callback()
        },
        // vr播放器设置
        applyVrPlayOptions(vrOptions = null) {
            if (this.currentToolbarCode === 'basic' || !this.vrViewer) {
                return
            }
            if (vrOptions) {
                this.vrOptions = merge(this.vrOptions, vrOptions)
            }
            // console.log('this.vrOptions:', this.vrOptions)
            // console.log('old this.vrOptions:', this.oldVrOptions)
            const that = this
            try {
                if (
                    this.vrOptions.defaultZoomLvl !== this.oldVrOptions.defaultZoomLvl
                ) {
                    this.vrViewer.zoom(this.vrOptions.defaultZoomLvl)
                }
                if (
                    this.vrOptions.defaultYaw !== this.oldVrOptions.defaultYaw ||
                    this.vrOptions.defaultPitch !== this.oldVrOptions.defaultPitch
                ) {
                    if (isNaN(this.vrOptions.defaultYaw)) {
                        this.vrOptions.defaultYaw = 0
                    }

                    if (isNaN(this.vrOptions.defaultPitch)) {
                        this.vrOptions.defaultPitch = 0
                    }

                    this.vrViewer.rotate({
                        yaw: this.vrOptions.defaultYaw,
                        pitch: this.vrOptions.defaultPitch,
                    })
                }

                // eslint-disable-next-line no-unused-vars
                Object.keys(this.vrOptions).some(function (key) {
                    // console.log('k:', key, 'i:', index)
                    if ('adapter' !== key && !isEqual(that.vrOptions[key], that.oldVrOptions[key])) {
                        // 自动旋转开始后的延迟，单位为毫秒。
                        // if ('autostartOnIdle' === key) {
                        //     that.viewer.setOption(
                        //         'autostartDelay',
                        //         that.vrOptions.autostartOnIdle ? 2000 : null
                        //     )
                        // }
                        that.vrViewer.setOption(key, that.vrOptions[key])
                        return true
                    }

                    return false
                })

                const sphereCorrection = merge(that.vrOptions.sphereCorrection || {}, {
                    pan: 0,
                    tilt: 0,
                    roll: 0,
                })
                this.vrViewer.setOption('sphereCorrection', {
                    pan: (sphereCorrection.pan / 180) * Math.PI,
                    tilt: (sphereCorrection.tilt / 180) * Math.PI,
                    roll: (sphereCorrection.roll / 180) * Math.PI,
                })
            } catch (_e) {
                console.error(_e)
            }
            this.oldVrOptions = cloneDeep(this.vrOptions)
        },
        // 渲染VR容器
        renderVR(sceneId = undefined, domId = 'viewer') {
            if (sceneId === undefined) {
                sceneId = this.currentScene.id
            }
            this.oldVrOptions = cloneDeep(this.vrOptions)
            const _render = (scene, resolve) => {
                this.currentScene = scene
                this.mergeRemoteSceneOptions(scene)
                // console.log('this.vrOption:', this.vrOptions)
                const options = {
                    container: domId,
                    loadingImg: require('@/assets/loader.gif'),
                    lang: {
                        autorotate: '自动旋转',
                        zoom: '缩放',
                        zoomOut: '缩小',
                        zoomIn: '放大',
                        moveUp: '向上移动',
                        moveDown: '向下移动',
                        moveLeft: '向左移动',
                        moveRight: '向右移动',
                        download: '下载',
                        fullscreen: '全屏',
                        menu: '菜单',
                        close: '关闭',
                        twoFingers: '用两个手指来导航',
                        ctrlZoom: '使用ctrl + scroll缩放图像',
                        loadError: '全景图无法加载',
                        map: '电子沙盘',
                        mapMaximize: '最大化',
                        mapMinimize: '最小化',
                        mapNorth: '指南针',
                        mapReset: '重置',
                    },
                    plugins: this.vrPlugins.concat([
                        [
                            MarkersPlugin,
                            {
                                //markers: this.hotpotMarkerItems, //this.hotpotMarkerItems
                                clickEventOnMarker: true,
                            },
                        ],
                    ]),
                }
                if (this.vrNavBars.length > 0) {
                    // options.navbar = DEFAULTS.navbar.concat(this.vrNavBars)
                    options.navbar = this.vrNavBars.concat(DEFAULTS.navbar)
                }
                let init = true
                if (!this.vrViewer) {
                    if (parseInt(this.currentScene.tileStatus) === 2) {
                        options.adapter = EquirectangularTilesAdapter
                    }
                    this.vrViewer = new Viewer(options)
                } else {
                    init = false
                    const tiledStatus = parseInt(this.currentScene.tileStatus)
                    // 当首次加载的adapter不是分片adapter时,第二次进入,判断如果当前分片完成同时首次加载的adapter是默认的,则需要销毁vr viewer
                    if (
                        tiledStatus === 2 &&
                        !(this.vrViewer.adapter instanceof EquirectangularTilesAdapter)
                    ) {
                        this.destroyVR()
                        options.adapter = EquirectangularTilesAdapter
                        this.vrViewer = new Viewer(options)
                    }

                    // 当首次加载的adapter是分片adapter时,第二次进入,由于服务降级等原因,需要使用默认的判断适配器,则需要销毁vr viewer
                    if (
                        tiledStatus !== 2 &&
                        this.vrViewer.adapter instanceof EquirectangularTilesAdapter
                    ) {
                        this.destroyVR()
                        this.vrViewer = new Viewer(options)
                    }
                }

                // console.log(this.vrViewer.adapter)
                this.initPanorama()
                this.renderVRCallback(init)
                resolve(1)
            }

            return new Promise((resolve) => {
                getScene(sceneId).then((scene) => _render(scene, resolve))
            })
        },
        // 初始化全景图
        initPanorama() {
            let panorama = this.currentScene.panoramaUrl
            const tiledStatus = parseInt(this.currentScene.tileStatus)
            if (tiledStatus === 2) {
                panorama = {
                    width: this.currentScene.panoramaWidth,
                    cols: this.currentScene.tileColumns,
                    rows: this.currentScene.tileRows,
                    baseUrl: this.currentScene.panoramaSmallUrl,
                    tileUrl: (col, row) => {
                        // const num = row * 16 + col + 1
                        return `${this.currentScene.tileUrl}/cp_${col}_${row}.jpg`
                    },
                }
            }

            let panoData = null
            if (parseInt(this.currentScene.panoramaWidth) > 0) {
                const panoramaWidth = parseInt(this.currentScene.panoramaWidth)
                const panoramaHeight = parseInt(this.currentScene.panoramaHeight)
                const fullWidth = Math.max(panoramaWidth, 2 * panoramaHeight)
                const fullHeight = Math.round(fullWidth / 2)
                panoData = {
                    fullWidth: fullWidth,
                    fullHeight: fullHeight,
                    croppedWidth: panoramaWidth,
                    croppedHeight: panoramaHeight,
                    croppedX: Math.round((fullWidth - panoramaWidth) / 2),
                    croppedY: Math.round((fullHeight - panoramaHeight) / 2),
                }
            }
            // console.log('panoData:', panoData)
            this.vrViewer.overlay.hide()
            if (panoData) {
                this.vrViewer.setPanorama(panorama, { panoData: panoData })
            } else {
                this.vrViewer.setPanorama(panorama)
            }
        },
        // 合并服务端保存的场景的参数
        mergeRemoteSceneOptions(scene) {
            this.vrOptions = Object.assign(this.vrOptions, Object.keys(scene.vrOptions).length ? scene.vrOptions : {})
        },
        // 销毁VR
        destroyVR() {
            this.vrViewer.destroy()
            this.vrViewer = null
            this.vrViewerLoaded = false
            this.hotpots = []
            this.hotpotMarkerItems = []
        },
        // 获取作品所有场景
        getProductScenes() {
            return getProductScenes(this.product.id)
        },
        //  初始化场景热点
        async initSceneHotPoints(sceneId, cb = null, params = {}) {
            const hotpots = await getHotpots(sceneId, params)
            this.hotpots = hotpots
            this.hotpotMarkerItems = []
            console.log('清除热点')
            this.markersPlugin.clearMarkers()
            hotpots.some((hotpot) => {
                if (hotpot.iconMarkerParams) {
                    hotpot.iconMarkerParams.data.content = hotpot.content
                    hotpot.iconMarkerParams.content = null
                    // console.log('hotpot:', hotpot)
                    // if ('usePlanPlugin' in params && params.usePlanPlugin) {
                    //     hotpot.iconMarkerParams.data['plan'] = {
                    //         coordinates: [27.420244, 101.689655],
                    //         size: 25,
                    //         image: 'https://photo-sphere-viewer-data.netlify.app/assets/pictos/pin-red.png'
                    //     }
                    // }
                    this.hotpotMarkerItems.push(hotpot.iconMarkerParams)
                }

                if (
                    typeof hotpot.iconTitleMarkerParams === 'object' &&
                    Object.keys(hotpot.iconTitleMarkerParams).length > 0
                ) {
                    hotpot.iconTitleMarkerParams.content = null
                    this.hotpotMarkerItems.push(hotpot.iconTitleMarkerParams)
                }
            })

            if (this.hotpotMarkerItems.length) {
                this.markersPlugin.setMarkers(this.hotpotMarkerItems)
                // this.$nextTick(() => {
                //     this.markersPlugin.setMarkers(this.hotpotMarkerItems)
                // })
            }
            typeof cb === 'function' && cb()
        },
        renderVRCallback() { }
    },
}